cd /workspace && cat > /tmp/verify_graph.mjs <<'EOF'
const BASE='http://localhost:5173';
let seen=new Set(), failed=[], ok=0;
async function fetchT(url){ try{ const r=await fetch(BASE+url,{signal:AbortSignal.timeout(20000)}); const t=await r.text(); return {status:r.status,text:t}; }catch(e){ return {status:'ERR',text:String(e)}; } }
async function walk(url){
  if(seen.has(url))return; seen.add(url);
  const {status,text}=await fetchT(url);
  if(status!==200){ failed.push(`${url} -> HTTP ${status}`); return; }
  if(/Failed to resolve|no such file|ErrorOverlay/i.test(text) && /"message"|vite/i.test(text)){
    // only count if it's actually a Vite error payload
    const m=text.match(/"message":"([^"]+)"/);
    if(m){ failed.push(`${url} -> ${m[1]}`); return; }
  }
  ok++;
  // find import specs
  const specs=new Set();
  for(const m of text.matchAll(/import\s*\(\s*["']([^"']+)["']\s*\)/g)) specs.add(m[1]);
  for(const m of text.matchAll(/from\s+["']([^"']+)["']/g)) specs.add(m[1]);
  for(const m of text.matchAll(/import\s+["']([^"']+)["']/g)) specs.add(m[1]);
  const dir=url.split('/').slice(0,-1).join('/');
  for(let s of specs){
    if(!s || s.startsWith('data:')) continue;
    let t=s;
    if(t.startsWith('@vite/')||t.startsWith('/@')) { t=t; }       // keep as-is (absolute from root)
    else if(t.startsWith('/')) { /* absolute */ }
    else if(t.startsWith('./')||t.startsWith('../')) t=dir?dir+'/'+t:t;
    else if(t.startsWith('node:')||!t.startsWith('/')) { if(!t.startsWith('node:')) continue; } // bare spec (node_modules) skip
    if(t.includes('?')) t=t; // keep query
    // normalize: if it's a root-relative path, ensure starts with /
    if(!t.startsWith('/') && !t.startsWith('@vite')) continue;
    // resolve relative
    if((s.startsWith('./')||s.startsWith('../'))) { t=require('url').resolve? '' : t; }
    // do robust relative join
    if(s.startsWith('./')||s.startsWith('../')){
      const parts=(dir? dir.split('/') : []).concat(s.split('/'));
      const out=[];
      for(const p of parts){ if(p==='.' ) continue; if(p==='..') out.pop(); else out.push(p); }
      t='/'+out.join('/');
    } else if(s.startsWith('@/')){
      t='/resources/js/'+s.slice(2);
    } else if(!s.startsWith('/') && !s.startsWith('@vite') && !s.startsWith('node:')){
      continue; // bare module specifier (node_modules) — skip
    }
    await walk(t);
  }
}
await walk('/resources/js/app.ts');
console.log('Modules resolved OK:', ok);
console.log('FAILED imports:', failed.length);
for(const f of failed) console.log('  ', f);
EOF
node /tmp/verify_graph.mjs 2>&1 | head -40; echo "NODE_EXIT=${PIPESTATUS[0]}"

